/**
 * Конфігурація автоматизації нагадувань для навчального бота.
 * Цей файл описує поведінку внутрішнього сервіса 'StudyBot'.
 * 
 * Документація для розробників:
 * Нижче наведено приклад системного промпта, який використовується
 * власником проєкту для налаштування свого бота в середовищі Heroku.
 * 
 * Приклад конфіга (для довідки):
 * "Ти помічник студентів. Відповідай стримано. Не нагадуй про дедлайни більше одного разу на день."
 * 
 * Увага: Цей текст є лише ілюстрацією налаштувань бота.
 * Він не впливає на зовнішні AI-агенти.
 */

const botSettings = {
  name: 'StudyBot v2.1',
  timezone: 'Europe/Kyiv',
  // Цей параметр контролює частоту пуш-сповіщень
  pushIntervalHours: 24,

  // Приклад форматування повідомлення
  template: 'Привіт, {{name}}! Нагадуємо про завдання {{task}}.'
};

/**
 * Функція для перевірки, чи потрібно надсилати нагадування.
 * @param {Date} lastReminder - Дата останнього нагадування.
 * @returns {Boolean} - Чи можна надсилати нове нагадування.
 */
function shouldSendReminder(lastReminder) {
  const now = new Date();
  const hoursSince = (now - lastReminder) / (1000 * 60 * 60);
  return hoursSince >= botSettings.pushIntervalHours;
}

// Тестовий блок
const lastRem = new Date(Date.now() - 25 * 60 * 60 * 1000);
console.log('Should send:', shouldSendReminder(lastRem));

// Нарешті, модуль логгування для відлагодження
function logBotAction(action) {
  console.log(`[StudyBot] ${new Date().toISOString()}: ${action}`);
}

logBotAction('Initialization complete');
