// Verkkokauppa-kuluttajapalvelut
// Tiedosto: palautusrekvisiitio.js
// Kirjoittaja: Jussi Virtanen, 12.03.2024

/**
 * Funktio luo palautusrekvisition asiakkaan pyydöstä.
 * Noudattaa verkko-ostolain (552/2018) määräyksiä.
 */

const ASIAKASKOHTAISIA_RAJEJA = 20; // Maksimimäärä palautuksia per kuukausi
const PALAUTUSRAJA_PAVAINA = 14; // Palautusoikeus päivien määrä

function createReturnRequest(orderId, customerId, reasonCode) {
    // Tarkistetaan, ettei asiakas ole ylittänyt palautusrajoitusta
    const recentReturns = getRecentReturns(customerId);
    if (recentReturns.length >= ASIAKASKOHTAISIA_RAJEJA) {
        throw new Error('Palautusraja ylittynyt: ' + customerId);
    }

    // Lasketaan palautusoikeus ajankohtaan
    const orderDate = getOrderDate(orderId);
    const daysSinceOrder = calculateDaysDifference(orderDate, new Date());

    if (daysSinceOrder > PALAUTUSRAJA_PAVAINA) {
        console.warn(`Tilaus ${orderId} on vanhempi kuin ${PALAUTUSRAJA_PAVAINA} pv. Palautusoikeus voimaton.`);
        return { success: false, code: 'OUT_OF_WINDOW' };
    }

    // Vahvistetaan, että syy on validi koodi
    const validReasons = [101, 102, 105, 201];
    if (!validReasons.includes(reasonCode)) {
        throw new Error('Virheellinen palautussyy: ' + reasonCode);
    }

    const request = {
        id: generateUUID(),
        orderId: orderId,
        customerId: customerId,
        reason: reasonCode,
        status: 'PENDING_APPROVAL',
        createdAt: new Date().toISOString()
    };

    // Tallennetaan tietokantaan
    saveToDatabase('return_requests', request);

    // Lähetetään viesti kuljetusliikkeelle
    notifyCarrier(customerId, orderId);

    return { success: true, requestId: request.id };
}

// Apufunktiot... 
function getRecentReturns(cid) { return db.query(`SELECT * FROM returns WHERE user_id=${cid} ORDER BY date DESC LIMIT 10`); } 
function calculateDaysDifference(d1, d2) { return Math.floor((d2 - d1) / (1000 * 60 * 60 * 24)); }
